module Computer_System_Video_In_Subsystem_avalon_st_adapter_data_format_adapter_0 (
    input clk,
    input reset_n,
    input [DATA_WIDTH-1:0] in_data,
    input in_valid,
    output reg out_valid,
    input out_ready,
    output reg [DATA_WIDTH-1:0] out_data,
    output reg out_startofpacket,
    output reg out_endofpacket,
    output reg out_empty
);

    parameter DATA_WIDTH = 8; // change to match data width

    // state machine states
    parameter STATE_IDLE = 2'b00;
    parameter STATE_WAIT_FOR_VALID = 2'b01;
    parameter STATE_OUTPUT = 2'b10;

    reg [1:0] state;
    reg [DATA_WIDTH-1:0] output_data;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state <= STATE_IDLE;
            out_valid <= 1'b0;
            out_startofpacket <= 1'b0;
            out_endofpacket <= 1'b0;
            out_empty <= 1'b1;
        end else begin
            case (state)
                STATE_IDLE: begin
                    if (in_valid) begin
                        state <= STATE_WAIT_FOR_VALID;
                    end else begin
                        out_valid <= 1'b0;
                        out_startofpacket <= 1'b0;
                        out_endofpacket <= 1'b0;
                        out_empty <= 1'b1;
                    end
                end
                STATE_WAIT_FOR_VALID: begin
                    if (out_ready) begin
                        output_data <= in_data; // convert data here
                        out_valid <= 1'b1;
                        out_startofpacket <= in_startofpacket;
                        out_endofpacket <= in_endofpacket;
                        out_empty <= 1'b0;
                        state <= STATE_OUTPUT;
                    end else begin
                        out_valid <= 1'b0;
                        out_startofpacket <= 1'b0;
                        out_endofpacket <= 1'b0;
                        out_empty <= 1'b1;
                    end
                end
                STATE_OUTPUT: begin
                    if (out_ready) begin
                        out_valid <= 1'b0;
                        out_startofpacket <= 1'b0;
                        out_endofpacket <= 1'b0;
                        out_empty <= 1'b1;
                        state <= STATE_IDLE;
                    end else begin
                        out_valid <= 1'b1;
                        out_startofpacket <= 1'b0;
                        out_endofpacket <= 1'b0;
                        out_empty <= 1'b0;
                    end
                end
            endcase
        end
    end

endmodule

module adder_subtractor(
    input [15:0] a,
    input [15:0] b,
    input sub,
    output [31:0] out
);

    wire [15:0] b_inverted;
    wire [15:0] b_complemented;
    wire [15:0] add_result;
    wire [15:0] sub_result;

    // XOR gate to invert b input when sub is 1
    xor #(.N(16)) xor_gate(
        .a(b),
        .b({16{sub}}),
        .y(b_inverted)
    );

    // 2's complement module to convert sub input to its 2's complement form
    twos_complement twos_comp(
        .in(b_inverted),
        .out(b_complemented)
    );

    // 16-bit adder module for add operation
    adder add(
        .a(a),
        .b(b),
        .out(add_result)
    );

    // 16-bit adder module for sub operation
    adder sub(
        .a(a),
        .b(b_complemented),
        .out(sub_result)
    );

    // Output selection based on sub and select inputs
    assign out = (sub) ? sub_result : add_result;

endmodule

