module m26_rx_ch
(
    input wire RST,
    input wire CLK_RX,
    input wire MKD_RX,
    input wire DATA_RX,

    output wire WRITE, FRAME_START,
    output wire [15:0] DATA

); 

reg [15:0] mkd_sr;
always@(posedge CLK_RX)
    mkd_sr[15:0] <= {mkd_sr[14:0], MKD_RX};

reg [15:0] data_sr;
always@(posedge CLK_RX)
    data_sr[15:0] <= {DATA_RX, data_sr[15:1]};

assign FRAME_START = (mkd_sr[15:12] == 4'b1111);

reg [15:0] data_cnt;
always@(posedge CLK_RX)
    if(RST)
        data_cnt <= 16'hffff;
    else if(FRAME_START)
        data_cnt <= 0;
    else if(data_cnt != 16'hffff)
        data_cnt <= data_cnt + 1;

reg [15:0] data_len;
always@(posedge CLK_RX)
    if(RST)
        data_len <= 0;
    else if(data_cnt==31)
        data_len <= data_sr;


assign WRITE = FRAME_START | data_cnt == 15 | data_cnt == 31 | ((data_cnt + 1) % 16 == 0 && data_cnt / 16 < data_len + 3);
assign DATA = data_sr;

endmodule

module up_down_counter_adder (
  input clk,
  input reset,
  input up_down,
  input [2:0] value,
  input slowena,
  input select,
  output reg [3:0] count,
  output reg [3:0] sum
);

  reg [3:0] count_reg;
  reg [3:0] sum_reg;
  wire [3:0] adder_out;

  always @(posedge clk) begin
    if (reset) begin
      count_reg <= 4'b0000;
      sum_reg <= 4'b0000;
    end else begin
      if (up_down) begin
        count_reg <= count_reg + 1;
      end else begin
        count_reg <= count_reg - 1;
      end
      if (!slowena) begin
        sum_reg <= count_reg + value;
      end
    end
  end

  assign adder_out = count_reg + value;

  always @(*) begin
    if (select) begin
      count = count_reg;
      sum = 4'bZZZZ;
    end else begin
      count = 4'bZZZZ;
      sum = sum_reg;
    end
  end

endmodule

