module barrel_shifter (
    input [3:0] data_in,
    input [2:0] shift_amount,
    input shift_direction,
    output [3:0] data_out
);

reg [3:0] shifted_data;

always @ (*) begin
    if (shift_direction == 0) begin
        shifted_data = data_in << shift_amount;
    end else begin
        shifted_data = data_in >> shift_amount;
    end
end

assign data_out = shifted_data;

endmodule

