module fifo(
    clk,
    reset,
    wr_en,
    rd_en,
    wr_data,
    rd_data, 
    not_full,
    not_empty,
    error
);

parameter DATA_WIDTH = 32;
parameter ADDR_WIDTH = 4;
localparam FIFO_SIZE = {1'b1, {(ADDR_WIDTH){1'b0}}};

input clk;
input reset;
input wr_en;
input rd_en;
input [DATA_WIDTH-1:0] wr_data;
output [DATA_WIDTH-1:0] rd_data;
output not_full;
output not_empty;
output error;

reg [DATA_WIDTH-1:0] queue[0:FIFO_SIZE-1];
reg [ADDR_WIDTH-1:0] rd_index;
reg [ADDR_WIDTH-1:0] wr_index;
reg [ADDR_WIDTH:0] count;

// Precompute several reused things

wire [ADDR_WIDTH-1:0] next_rd_index = rd_index + 1'b1;
wire [ADDR_WIDTH-1:0] next_wr_index = wr_index + 1'b1;

wire [ADDR_WIDTH:0] increase_count = count + 1'b1;
wire [ADDR_WIDTH:0] decrease_count = count - 1'b1;

always @(posedge clk or posedge reset)
begin
    if (reset)
    begin
        wr_index <= 1'b0;
        rd_index <= 1'b0;
        count <= 1'b0;
        error <= 1'b0;
    end
    else if (rd_en & wr_en)
    begin
        // Read and write at the same time
        queue[wr_index] <= wr_data;
        rd_index <= next_rd_index;
        wr_index <= next_wr_index;
        count <= count;
    end
    else if (wr_en)
    begin
        // Only write
        if (count == FIFO_SIZE) begin
            queue[wr_index] <= wr_data;
            rd_index <= next_rd_index;
            wr_index <= next_wr_index;
            error <= 1'b0;
        end else begin
            queue[wr_index] <= wr_data;
            wr_index <= next_wr_index;
            count <= increase_count;
            error <= 1'b0;
        end
    end
    else if (rd_en)
    begin
        // Only read
        if (count == 1'b0) begin
            rd_index <= rd_index;
            wr_index <= wr_index;
            error <= 1'b1;
        end else begin
            rd_index <= next_rd_index;
            count <= decrease_count;
            error <= 1'b0;
        end
    end
end

assign not_full = ~count[ADDR_WIDTH];
assign not_empty = |count;
assign rd_data = queue[rd_index];

endmodule

module ad_jesd_align (

  // jesd interface

  rx_clk,
  rx_ip_sof,
  rx_ip_data,
  rx_sof,
  rx_data);

  // jesd interface

  input           rx_clk;
  input   [ 3:0]  rx_ip_sof;
  input   [31:0]  rx_ip_data;

  // aligned data

  output          rx_sof;
  output  [31:0]  rx_data;

  // internal registers

  reg     [31:0]  rx_ip_data_d = 'd0;
  reg     [ 3:0]  rx_ip_sof_hold = 'd0;
  reg             rx_sof = 'd0;
  reg             rx_ip_sof_d = 'd0;
  reg     [31:0]  rx_data = 'd0;

  // dword may contain more than one frame per clock
  always @(posedge rx_clk) begin
    rx_ip_data_d <= rx_ip_data;
    rx_ip_sof_d <= rx_ip_sof;
    if (rx_ip_sof != 4'h0) begin
      rx_ip_sof_hold <= rx_ip_sof;
    end
    rx_sof <= |rx_ip_sof_d;
    if (rx_ip_sof_hold[0] == 1'b1) begin
      rx_data <= rx_ip_data;
    end else if (rx_ip_sof_hold[1] == 1'b1) begin
      rx_data <= {rx_ip_data[ 7:0], rx_ip_data_d[31: 8]};
    end else if (rx_ip_sof_hold[2] == 1'b1) begin
      rx_data <= {rx_ip_data[15:0], rx_ip_data_d[31:16]};
    end else if (rx_ip_sof_hold[3] == 1'b1) begin
      rx_data <= {rx_ip_data[23:0], rx_ip_data_d[31:24]};
    end else begin
      rx_data <= 32'd0;
    end
  end

