  CrcHashGood <= StateData[0] & ByteCntEq6;
end

always @ (posedge MRxClk) begin
  if (Reset | StateIdle) begin
    CrcHash[5:0] <= 6'h0;
  end else begin
    if (StateData[0] & ByteCntEq6) begin
      CrcHash[5:0] <= Crc[31:26];
    end
  end
end

always @ (posedge MRxClk or posedge Reset) begin
  if (Reset) begin
    RxData_d[7:0] <= 8'h0;
    DelayData <= 1'b0;
    LatchedByte[7:0] <= 8'h0;
    RxData[7:0] <= 8'h0;
  end else begin
    LatchedByte[7:0] <= {MRxD[3:0], LatchedByte[7:4]};
    DelayData <= StateData[0];
    if (GenerateRxValid) begin
      RxData_d[7:0] <= LatchedByte[7:0] & {8{|StateData}};
    end else begin
      if (~DelayData) begin
        RxData_d[7:0] <= 8'h0;
      end
    end
    RxData[7:0] <= RxData_d[7:0];
  end
end

always @ (posedge MRxClk or posedge Reset) begin
  if (Reset) begin
    Broadcast <= 1'b0;
  end else begin      
    if (StateData[0] & ~(&LatchedByte[7:0]) & ByteCntSmall7) begin
      Broadcast <= 1'b0;
    end else begin
      if (StateData[0] & (&LatchedByte[7:0]) & ByteCntEq1) begin
        Broadcast <= 1'b1;
      end else begin
        if (RxAbort | RxEndFrm) begin
          Broadcast <= 1'b0;
        end
      end
    end
  end
end

always @ (posedge MRxClk or posedge Reset) begin
  if (Reset) begin
    Multicast <= 1'b0;
  end else begin      
    if (StateData[0] & ByteCntEq1 & LatchedByte[0]) begin
      Multicast <= 1'b1;
    end else if (RxAbort | RxEndFrm) begin
      Multicast <= 1'b0;
    end
  end
end

assign GenerateRxValid = StateData[0] & (~ByteCntEq0 | DlyCrcCnt >= 4'h3);

always @ (posedge MRxClk or posedge Reset) begin
  if (Reset) begin
    RxValid_d <= 1'b0;
    RxValid <= 1'b0;
  end else begin
    RxValid_d <= GenerateRxValid;
    RxValid <= RxValid_d;
  end
end

assign GenerateRxStartFrm = StateData[0] & ((ByteCntEq1 & ~DlyCrcEn) | ((DlyCrcCnt == 4'h3) & DlyCrcEn));

always @ (posedge MRxClk or posedge Reset) begin
  if (Reset) begin
    RxStartFrm_d <= 1'b0;
    RxStartFrm <= 1'b0;
  end else begin
    RxStartFrm_d <= GenerateRxStartFrm;
    RxStartFrm <= RxStartFrm_d;
  end
end

assign GenerateRxEndFrm = StateData[0] & (~MRxDV & ByteCntGreat2 | ByteCntMaxFrame);
assign DribbleRxEndFrm = StateData[1] & ~MRxDV & ByteCntGreat2;

always @ (posedge MRxClk or posedge Reset) begin
  if (Reset) begin
    RxEndFrm_d <= 1'b0;
    RxEndFrm <= 1'b0;
  end else begin
    RxEndFrm_d <= GenerateRxEndFrm;
    RxEndFrm <= RxEndFrm_d | DribbleRxEndFrm;
  end
end

endmodule

module traffic_light_controller (
  input clk,
  input reset,
  input [1:0] state_in,
  output reg [1:0] state_out,
  output reg red,
  output reg green
);

  reg [2:0] state;
  reg [2:0] next_state;

  always @(posedge clk, posedge reset) begin
    if (reset) begin
      state <= 3'b000;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      3'b000: begin // red light on
        state_out = 3'b000;
        red = 1'b1;
        green = 1'b0;
        next_state = 3'b001;
      end
      3'b001: begin // green light on
        state_out = 3'b001;
        red = 1'b0;
        green = 1'b1;
        next_state = 3'b010;
      end
      3'b010: begin // yellow light on
        state_out = 3'b010;
        red = 1'b1;
        green = 1'b0;
        next_state = 3'b011;
      end
      3'b011: begin // red light on
        state_out = 3'b000;
        red = 1'b1;
        green = 1'b0;
        next_state = 3'b000;
      end
      default: begin // should never happen
        state_out = 3'b000;
        red = 1'b1;
        green = 1'b0;
        next_state = 3'b000;
      end
    endcase
  end

endmodule

