module BOR (
  input vcc,
  input vref,
  output reg rst_n
);

parameter vth = 3.0; // threshold voltage for BOR circuit

reg vcc_filtered; // filtered vcc signal

// Low-pass filter to remove noise from vcc signal
always @ (posedge vcc) begin
  vcc_filtered <= (vcc_filtered + vcc) / 2;
end

// BOR circuit logic
always @ (vcc_filtered, vref) begin
  if (vcc_filtered < vref - vth) begin
    rst_n <= 0;
  end else begin
    rst_n <= 1;
  end
end

endmodule

module ripple_carry_adder (
    input wire [3:0] a, b,
    output wire [3:0] sum,
    output wire cout,
    output wire overflow
);

    wire [3:0] c;
    assign c[0] = 1'b0;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : adder
            full_adder fa(
                .a(a[i]),
                .b(b[i]),
                .cin(c[i]),
                .sum(sum[i]),
                .cout(c[i+1])
            );
        end
    endgenerate

    assign cout = c[4];
    assign overflow = (a[3] & b[3] & ~sum[3]) | (~a[3] & ~b[3] & sum[3]);

endmodule

