  assign mux_out[0] = (sel == 2'b00) ? in0[0] : (sel == 2'b01) ? in1[0] : (sel == 2'b10) ? in2[0] : in3[0];
  assign mux_out[1] = (sel == 2'b00) ? in0[1] : (sel == 2'b01) ? in1[1] : (sel == 2'b10) ? in2[1] : in3[1];
  assign mux_out[2] = (sel == 2'b00) ? in0[2] : (sel == 2'b01) ? in1[2] : (sel == 2'b10) ? in2[2] : in3[2];
  assign mux_out[3] = (sel == 2'b00) ? in0[3] : (sel == 2'b01) ? in1[3] : (sel == 2'b10) ? in2[3] : in3[3];

  assign out = (en == 1'b1) ? mux_out : 4'b0000;

endmodule

module shift_register(clk, reset, load, data_in, data_out);

parameter WIDTH = 16;

input clk, reset, load;
input [WIDTH-1:0] data_in;
output [WIDTH-1:0] data_out;

reg [WIDTH-1:0] register;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        register <= 0;
    end else begin
        if (load) begin
            register <= data_in;
        end else begin
            register <= {register[WIDTH-2:0], 1'b0};
        end
    end
end

assign data_out = register;

endmodule

module fifo_buffer
  #(parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 13)
  (
    input rd_clk,
    input wr_clk,
    input tmp_ram_rd_en,
    input [0:0] WEBWE,
    input [DATA_WIDTH-1:0] Q,
    output reg [DATA_WIDTH-1:0] dout,
    output reg [ADDR_WIDTH-1:0] count_d1_reg
  );

  reg [DATA_WIDTH-1:0] mem [0:(1<<ADDR_WIDTH)-1];
  reg [ADDR_WIDTH-1:0] head_ptr = 0;
  reg [ADDR_WIDTH-1:0] tail_ptr = 0;
  reg [ADDR_WIDTH-1:0] count = 0;

  always @(posedge wr_clk) begin
    if (WEBWE) begin
      mem[head_ptr] <= Q;
      head_ptr <= (head_ptr == (1<<ADDR_WIDTH)-1) ? 0 : head_ptr + 1;
      count <= count + 1;
    end
  end

  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && count > 0) begin
      dout <= mem[tail_ptr];
      tail_ptr <= (tail_ptr == (1<<ADDR_WIDTH)-1) ? 0 : tail_ptr + 1;
      count <= count - 1;
    end
  end

  always @(posedge wr_clk or posedge rd_clk) begin
    count_d1_reg <= count;
  end

endmodule

module add_sub(
    input [31:0] a,
    input [31:0] b,
    input sub,
    output [31:0] sum
);

    wire [15:0] a_lo = a[15:0];
    wire [15:0] a_hi = a[31:16];
    wire [15:0] b_lo = b[15:0];
    wire [15:0] b_hi = b[31:16];
    wire [15:0] sum_lo;
    wire [15:0] sum_hi;

    // First 16-bit adder
    ripple_adder adder_lo(
        .a(a_lo),
        .b(sub ? ~b_lo : b_lo),
        .cin(sub),
        .sum(sum_lo)
    );

    // Second 16-bit adder
    ripple_adder adder_hi(
        .a(a_hi),
        .b(sub ? ~b_hi : b_hi),
        .cin(adder_lo.cout),
        .sum(sum_hi)
    );

    // 32-bit XOR gate
    assign sum = {sum_hi, sum_lo} ^ (sub ? -1 : 0);

endmodule

module divider (
    Y,
    Z,
    X
);

    output Y;
    output Z;
    input X;

    reg [31:0] counter_1;
    reg [31:0] counter_2;

    always @(posedge X) begin
        counter_1 <= counter_1 + 1;
        counter_2 <= counter_2 + 1;

        if (counter_1 == 10) begin
            Y <= 1;
            counter_1 <= 0;
        end else begin
            Y <= 0;
        end

        if (counter_2 == 20) begin
            Z <= 1;
            counter_2 <= 0;
        end else begin
            Z <= 0;
        end
    end

endmodule

module PLL_DLL (
  input ref_clk,
  input fb_clk,
  input sel,
  output out_clk
);

// module parameters
parameter ref_freq = 100; // frequency of the reference clock in MHz
parameter fb_freq = 120;  // frequency of the feedback clock in MHz
parameter sel_width = 1;  // width of the select signal

// module IO definitions
input [sel_width-1:0] sel;
input ref_clk;
input fb_clk;
output out_clk;

// PLL components
reg [31:0] phase_accumulator;
reg [31:0] phase_detector_output;
reg [31:0] loop_filter_output;
reg [31:0] vco_output;
reg [31:0] vco_frequency;
reg [31:0] vco_phase;

// DLL components
reg [31:0] delay_line_output;
reg [31:0] delay_line_input;
reg [31:0] delay_detector_output;
reg [31:0] delay_filter_output;
reg [31:0] delay_output;

// constants
localparam phase_detector_gain = 100;
localparam loop_filter_gain = 100;
localparam vco_gain = 100;
localparam delay_detector_gain = 100;
localparam delay_filter_gain = 100;

// reference clock divider
reg [31:0] ref_clk_divider;
always @(posedge ref_clk) begin
  ref_clk_divider <= ref_clk_divider + 1;
end

// feedback clock divider
reg [31:0] fb_clk_divider;
always @(posedge fb_clk) begin
  fb_clk_divider <= fb_clk_divider + 1;
end

// phase detector
always @(posedge ref_clk_divider or posedge fb_clk_divider) begin
  if (sel == 0) begin
    phase_detector_output <= (fb_clk_divider > ref_clk_divider) ? (fb_clk_divider - ref_clk_divider) : (ref_clk_divider - fb_clk_divider);
  end else begin
    phase_detector_output <= (fb_clk_divider > delay_line_output) ? (fb_clk_divider - delay_line_output) : (delay_line_output - fb_clk_divider);
  end
end

// loop filter
always @(posedge ref_clk_divider) begin
  if (sel == 0) begin
    loop_filter_output <= loop_filter_output + (phase_detector_output * loop_filter_gain);
  end else begin
    delay_filter_output <= delay_filter_output + (delay_detector_output * delay_filter_gain);
  end
end

// VCO
always @(posedge ref_clk_divider) begin
  if (sel == 0) begin
    vco_frequency <= loop_filter_output * vco_gain;
    vco_phase <= vco_phase + vco_frequency;
    vco_output <= vco_phase[31];
  end else begin
    delay_output <= delay_filter_output;
  end
end

// delay line
always @(posedge ref_clk) begin
  if (sel == 1) begin
    delay_line_input <= ref_clk;
    delay_line_output <= delay_line_input;
  end
end

// delay detector
always @(posedge ref_clk_divider or posedge fb_clk_divider) begin
  if (sel == 1) begin
    delay_detector_output <= (delay_line_output > fb_clk_divider) ? (delay_line_output - fb_clk_divider) : (fb_clk_divider - delay_line_output);
  end
end

// output clock
always @(posedge fb_clk) begin
  if (sel == 0) begin
    out_clk <= vco_output;
  end else begin
    out_clk <= #delay_output fb_clk;
  end
end

endmodule

module top_module (
    input [3:0] A,
    input [3:0] B,
    output eq,
    output gt,
    input C,
    input [3:0] D,
    output [3:0] final_output
);

    // 4-bit magnitude comparator
    wire [3:0] eq_temp;
    wire [3:0] gt_temp;
    assign eq_temp = (A == B);
    assign gt_temp = (A > B);
    assign eq = eq_temp[3] & eq_temp[2] & eq_temp[1] & eq_temp[0];
    assign gt = gt_temp[3] & gt_temp[2] & gt_temp[1] & gt_temp[0];

    // 4-bit barrel shifter
    wire [3:0] shifted_value;
    assign shifted_value = (C == 0) ? (A << D) : (A >> D);

    // Functional module
    assign final_output = eq & gt & shifted_value;

endmodule

module prng_module (
    input                clk,
    input                reset,
    input                [2:0] sel, // Selection input for the encoder
    input                [3:0] data0, // Input data 0 for encoder
    input                [3:0] data1, // Input data 1 for encoder
    input                [3:0] data2, // Input data 2 for encoder
    input                [3:0] data3, // Input data 3 for encoder
    input                [3:0] data4, // Input data 4 for encoder
    input                [3:0] data5, // Input data 5 for encoder
    output               [63:0] out // 64-bit output from the PRNG module
);

reg [63:0] shift_reg;
reg [5:0] enc_in;
wire [5:0] enc_out;
wire feedback;

assign feedback = shift_reg[63] ^ shift_reg[60] ^ shift_reg[52] ^ shift_reg[49];

priority_encoder_6to1 enc (
