            X = 2'b00;
            Y = 1'b1;
        end
        4'b0010: begin
            X = 2'b01;
            Y = 1'b1;
        end
        4'b0100: begin
            X = 2'b10;
            Y = 1'b1;
        end
        4'b1000: begin
            X = 2'b11;
            Y = 1'b1;
        end
        default: begin
            X = 2'b00;
            Y = 1'b0;
        end
    endcase
end

