    input signed [3:0] SHIFT,
    input RESET,
    output reg [3:0] OUT
);

reg [3:0] shifted_data;

always @ (DATA or SHIFT or RESET) begin
    if (RESET) begin
        shifted_data <= 4'b0000;
    end else if (SHIFT > 0) begin
        shifted_data <= {DATA[SHIFT-1:0], 2'b00};
    end else if (SHIFT < 0) begin
        shifted_data <= {2'b00, DATA[3:abs(SHIFT)]};
    end else begin
        shifted_data <= DATA;
    end
end

