module binary_to_bcd_converter (
    input [3:0] BIN,
    output [3:0] BCD_HIGH,
    output [3:0] BCD_LOW
);
    reg [3:0] stage1_out;
    reg [3:0] stage2_out;
    reg [3:0] stage3_out;

    // Stage 1
    always @* begin
        case(BIN)
            4'b0000: stage1_out = 4'b0000;
            4'b0001: stage1_out = 4'b0000;
            4'b0010: stage1_out = 4'b0000;
            4'b0011: stage1_out = 4'b0001;
            4'b0100: stage1_out = 4'b0000;
            4'b0101: stage1_out = 4'b0001;
            4'b0110: stage1_out = 4'b0001;
            4'b0111: stage1_out = 4'b0010;
            4'b1000: stage1_out = 4'b0000;
            4'b1001: stage1_out = 4'b0010;
            4'b1010: stage1_out = 4'b0010;
            4'b1011: stage1_out = 4'b0011;
            4'b1100: stage1_out = 4'b0001;
            4'b1101: stage1_out = 4'b0011;
            4'b1110: stage1_out = 4'b0011;
            4'b1111: stage1_out = 4'b0100;
        endcase
    end

    // Stage 2
    always @* begin
        case(stage1_out)
            4'b0000: stage2_out = 4'b0000;
            4'b0001: stage2_out = 4'b0001;
            4'b0010: stage2_out = 4'b0010;
            4'b0011: stage2_out = 4'b0011;
            4'b0100: stage2_out = 4'b0001;
            4'b0101: stage2_out = 4'b0010;
            4'b0110: stage2_out = 4'b0011;
            4'b0111: stage2_out = 4'b0100;
            4'b1000: stage2_out = 4'b0001;
            4'b1001: stage2_out = 4'b0010;
            4'b1010: stage2_out = 4'b0011;
            4'b1011: stage2_out = 4'b0100;
            4'b1100: stage2_out = 4'b0010;
            4'b1101: stage2_out = 4'b0100;
            4'b1110: stage2_out = 4'b0101;
            4'b1111: stage2_out = 4'b0110;
        endcase
    end

    // Stage 3
    always @* begin
        case(stage2_out)
            4'b0000: stage3_out = 4'b0000;
            4'b0001: stage3_out = 4'b0001;
            4'b0010: stage3_out = 4'b0010;
            4'b0011: stage3_out = 4'b0011;
            4'b0100: stage3_out = 4'b0100;
            4'b0101: stage3_out = 4'b0101;
            4'b0110: stage3_out = 4'b0110;
            4'b0111: stage3_out = 4'b0111;
            4'b1000: stage3_out = 4'b0001;
            4'b1001: stage3_out = 4'b0010;
            4'b1010: stage3_out = 4'b0011;
            4'b1011: stage3_out = 4'b0100;
            4'b1100: stage3_out = 4'b0101;
            4'b1101: stage3_out = 4'b0110;
            4'b1110: stage3_out = 4'b0111;
            4'b1111: stage3_out = 4'b1000;
        endcase
    end

    assign BCD_HIGH = stage3_out;
    assign BCD_LOW = stage2_out;

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);

reg [1:0] count;
reg [9:0] acc;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        count <= 2'b0;
        acc <= 10'b0;
        valid_b <= 1'b0;
    end else begin
        if (valid_a) begin
            case (count)
                2'b00: begin
                    acc <= acc + data_in;
                    count <= 2'b01;
                end
                2'b01: begin
                    acc <= acc + data_in;
                    count <= 2'b10;
                end
                2'b10: begin
                    acc <= acc + data_in;
                    count <= 2'b11;
                end
                2'b11: begin
                    acc <= acc + data_in;
                    count <= 2'b00;
                    valid_b <= 1'b1;
                end
            endcase
        end
    end
end

assign ready_a = ~valid_b & ready_b;
assign data_out = valid_b ? acc : 10'b0;

endmodule

module GlitchFreeClockMux (
  input [n-1:0] clk,
  input sel,
  output gclk
);

parameter n = 4; // number of input clock signals

reg [n-1:0] sync_clk;
reg [n-1:0] glitch_free_clk;

always @(posedge clk[0] or posedge clk[1] or posedge clk[2] or posedge clk[3] or posedge sel) begin
  // Compare the input clock signals and select the one with the best timing characteristics
  case(sel)
    0: sync_clk <= clk[0];
    1: sync_clk <= clk[1];
    2: sync_clk <= clk[2];
    3: sync_clk <= clk[3];
    default: sync_clk <= clk[0];
  endcase
end

// Synchronizer circuit to remove any glitches from the selected clock signal
always @(posedge sync_clk[0] or posedge sync_clk[1] or posedge sync_clk[2] or posedge sync_clk[3]) begin
  case(sel)
    0: glitch_free_clk <= sync_clk[0];
    1: glitch_free_clk <= sync_clk[1];
    2: glitch_free_clk <= sync_clk[2];
    3: glitch_free_clk <= sync_clk[3];
    default: glitch_free_clk <= sync_clk[0];
  endcase
end

assign gclk = glitch_free_clk;

endmodule

module stack_pointer(
  input CLK,
  input RST,
  input DECR,
  input INCR,
  input [7:0] DATA,
  input LD,
  output reg [7:0] Q
);

  reg [7:0] stack[0:7];
  reg [2:0] sp;

  always @(posedge CLK) begin
    if (RST) begin
      sp <= 0;
      Q <= 0;
    end else begin
      if (LD) begin
        stack[sp] <= DATA;
        sp <= (sp == 7) ? 0 : sp + 1;
      end else if (DECR) begin
        sp <= (sp == 0) ? 7 : sp - 1;
      end else if (INCR) begin
        sp <= (sp == 7) ? 0 : sp + 1;
      end
      Q <= stack[sp];
    end
  end

endmodule

module servo_control (
  input clk,
  input rst,
  input [15:0] pwm_in,
  output reg [15:0] pwm_out
);

parameter min_pulse_width = 1000; // in microseconds
parameter max_pulse_width = 2000; // in microseconds
parameter frequency = 50; // in Hz
parameter resolution = 16; // in bits

reg [15:0] counter = 0;
reg [15:0] threshold = 0;

always @(posedge clk) begin
  if (rst) begin
    pwm_out <= min_pulse_width;
    counter <= 0;
    threshold <= 0;
  end else begin
    counter <= counter + 1;
    if (counter == resolution) begin
      counter <= 0;
      threshold <= pwm_in;
    end
    if (threshold > counter) begin
      pwm_out <= max_pulse_width;
    end else begin
      pwm_out <= min_pulse_width;
    end
  end
end

endmodule

