module priority_encoder_module (
    input wire [7:0] in,
    output reg [2:0] pos
);

    always @(*) begin
        casez(in)
            8'b00000001: pos = 0;
            8'b00000010: pos = 1;
            8'b00000100: pos = 2;
            8'b00001000: pos = 3;
            8'b00010000: pos = 4;
            8'b00100000: pos = 5;
            8'b01000000: pos = 6;
            8'b10000000: pos = 7;
            default: pos = 3'b111;
        endcase
    end

endmodule


module functional_module (
    input wire [7:0] in1,
    input wire [7:0] in2,
    input wire [2:0] pos1,
    input wire [2:0] pos2,
    output reg [7:0] out
);

    always @(*) begin
        case ({pos1, pos2})
            3'b000: out = in1 & in2;
            3'b001: out = in1 & (in2 >> 1);
            3'b010: out = in1 & (in2 >> 2);
            3'b011: out = in1 & (in2 >> 3);
            3'b100: out = (in1 >> 1) & in2;
            3'b101: out = (in1 >> 1) & (in2 >> 1);
            3'b110: out = (in1 >> 2) & (in2 >> 1);
            3'b111: out = (in1 >> 3) & (in2 >> 1);
        endcase
    end

endmodule

