module AGC (
  input [15:0] input_signal,
  input [7:0] control_signal,
  output [15:0] output_signal
);

parameter gain_bits = 8; // number of bits used to represent the gain value

reg [gain_bits-1:0] gain_value; // binary value representing the gain
reg [15:0] adjusted_signal; // signal with constant output level

// Function to adjust the gain based on the control signal
function [gain_bits-1:0] adjust_gain;
  input [7:0] control;
  begin
    case (control)
      8'h00: adjust_gain = 8'h00; // no gain adjustment
      8'h01: adjust_gain = 8'h01; // small gain increase
      8'h02: adjust_gain = 8'h02;
      8'h03: adjust_gain = 8'h03;
      8'h04: adjust_gain = 8'h04;
      8'h05: adjust_gain = 8'h05;
      8'h06: adjust_gain = 8'h06;
      8'h07: adjust_gain = 8'h07;
      8'h08: adjust_gain = 8'h08; // maximum gain increase
      8'h09: adjust_gain = 8'h09; // no gain adjustment
      8'h0A: adjust_gain = 8'h0A;
      8'h0B: adjust_gain = 8'h0B;
      8'h0C: adjust_gain = 8'h0C;
      8'h0D: adjust_gain = 8'h0D;
      8'h0E: adjust_gain = 8'h0E;
      8'h0F: adjust_gain = 8'h0F;
      8'h10: adjust_gain = 8'h10; // maximum gain reduction
      8'h11: adjust_gain = 8'h11; // no gain adjustment
      8'h12: adjust_gain = 8'h12;
      8'h13: adjust_gain = 8'h13;
      8'h14: adjust_gain = 8'h14;
      8'h15: adjust_gain = 8'h15;
      8'h16: adjust_gain = 8'h16;
      8'h17: adjust_gain = 8'h17;
      8'h18: adjust_gain = 8'h18; // small gain reduction
      default: adjust_gain = 8'h00; // no gain adjustment
    endcase
  end
endfunction

// Assign the gain value based on the control signal
always @ (control_signal) begin
  gain_value = adjust_gain(control_signal);
end

// Compute the adjusted signal with constant output level
always @ (input_signal, gain_value) begin
  adjusted_signal = input_signal * gain_value;
end

// Assign the output signal
assign output_signal = adjusted_signal;

endmodule

module mux_johnson_counter(
  input                clk,
  input                rst_n,
  input [2:0]          sel,
  input [3:0]          data,
  output reg [3:0]     Q
);

  reg [3:0] shift_reg;
  reg [1:0] state = 2'b00;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      shift_reg <= 4'b0000;
      state <= 2'b00;
    end else begin
      shift_reg <= {shift_reg[2:0], data[sel]};
      case (state)
        2'b00: begin
          Q <= shift_reg[3:0];
          state <= 2'b01;
        end
        2'b01: begin
          Q <= shift_reg[2:0];
          state <= 2'b11;
        end
        2'b11: begin
          Q <= shift_reg[1:0] ^ shift_reg[3];
          state <= 2'b10;
        end
        2'b10: begin
          Q <= shift_reg[0] ^ shift_reg[2];
          state <= 2'b01;
        end
      endcase
    end
  end

endmodule

module vga_sync(

input wire clock,
input wire aresetn,

input wire [2:0] color,

output wire vga_clk,

output reg [7:0] R,
output reg [7:0] G,
output reg [7:0] B,

output reg h_sync,
output reg v_sync,

output wire blank_n,
output wire sync_n
);

/*
	VGA Frequency:   72Hz
	VGA Resolution:  800x600
	VGA Pixel Clock: 50MHz
*/

//Horizontal Parameters
localparam	H_FRONT		  =	56;
localparam	H_SYNC		  =	120;
localparam	H_BACK		  =	64;
localparam	H_ACT	   	  =	800;
localparam	H_BLANK		  =	H_FRONT+H_SYNC+H_BACK;
localparam	H_TOTAL		  =	H_FRONT+H_SYNC+H_BACK+H_ACT;
localparam  H_TOTAL_WIDTH =   10;

//Vertical Parameters
localparam	V_FRONT		  =	37;
localparam	V_SYNC		  =	6;
localparam	V_BACK		  =	23;
localparam	V_ACT	   	  =	600;
localparam	V_BLANK		  =	V_FRONT+V_SYNC+V_BACK;
localparam	V_TOTAL		  =	V_FRONT+V_SYNC+V_BACK+V_ACT;
localparam  V_TOTAL_WIDTH =   10;

//Clock
assign vga_clk = ~clock;

//Position Info
reg [(H_TOTAL_WIDTH-1):0] hor_pos;
reg [(V_TOTAL_WIDTH-1):0] ver_pos;

//Horizontal Data
always @(posedge clock) begin
	if (~aresetn)	
		begin
			hor_pos <= 'd0;
			h_sync  <= 1'b0;
		end
	else
		begin
			if (hor_pos < H_TOTAL)	hor_pos <= hor_pos + 1;
			else 							hor_pos <= 0;

			if (hor_pos == H_FRONT-1) 			h_sync <= 1'b1;
			if (hor_pos == H_FRONT+H_SYNC-1) h_sync <= 1'b0;

		end
end

//Vertical Data
always @(posedge h_sync) begin
	if (~aresetn)	
		begin
			ver_pos <= 'd0;
			v_sync  <= 1'b0;
		end
	else
		begin
			if (ver_pos < V_TOTAL)	ver_pos <= ver_pos + 1;
			else 							ver_pos <= 0;

			if (ver_pos == V_FRONT-1) 			v_sync <= 1'b1;
			if (ver_pos == V_FRONT+V_SYNC-1) v_sync <= 1'b0;

		end
end

//RGB Data
always @(posedge clock) begin
	if (~aresetn) 
		begin
			R <= 8'd0;
			B <= 8'd0;
			G <= 8'd0;
		end
	else if ((hor_pos < H_BLANK) | (ver_pos < V_BLANK))
		begin
			R <= 8'd0;
			B <= 8'd0;
			G <= 8'd0;		
		end
	else 
		begin
			if (color == 3'b100)
				begin
					R <= hor_pos[7:0];
					G <= ver_pos[7:0];
					B <= hor_pos[7:0];		
				end
			else if (color == 3'b110)
				begin
					R <= 8'd255;
					G <= 8'd0;
					B <= 8'd0;		
				end	
			else if (color == 3'b101)
				begin
					R <= 8'd0;
					G <= 8'd255;
					B <= 8'd0;		
				end	
			else if (color == 3'b011)
				begin
					R <= 8'd0;
					G <= 8'd0;
					B <= 8'd255;		
				end	
			else 
				begin
					R <= R;
					G <= G;
					B <= B;					
				end
		end
end

//Blank (ADV7123)
assign blank_n = ~((hor_pos < H_BLANK)||(ver_pos < V_BLANK));

//Sync (ADV7123)
assign sync_n  = 1'b1; 

endmodule

module fan_controller(
    input reset,
    output fan
);

reg rsi_MRST_reset;
reg csi_MCLK_clk;
reg [31:0] avs_ctrl_writedata;
wire [31:0] avs_ctrl_readdata;
reg [3:0] avs_ctrl_byteenable;
reg [2:0] avs_ctrl_address;
reg avs_ctrl_write;
reg avs_ctrl_read;
wire avs_ctrl_waitrequest;
reg rsi_PWMRST_reset;
reg csi_PWMCLK_clk;

fan_motor_driver fan_driver(
    .rsi_MRST_reset(rsi_MRST_reset),
    .csi_MCLK_clk(csi_MCLK_clk),
    .avs_ctrl_writedata(avs_ctrl_writedata),
    .avs_ctrl_readdata(avs_ctrl_readdata),
