    temp = in;
    for (i = 0; i < 8; i = i + 1) begin
        temp = {temp[127:0] + temp[255:128], temp[383:256] + temp[511:384], temp[639:512] + temp[767:640], temp[895:768] + temp[1023:896]};
    end
    q = temp[(sel*4)+3:(sel*4)];
end

