always @(*) begin
    case (op)
        2'b00: temp = sum + mux_out;
        2'b01: temp = sum - mux_out;
        2'b10: temp = sum * mux_out;
        default: temp = sum + mux_out;
    endcase
    q = temp;
end

endmodule

