module top_module (
    input [1:0] in,    // Input for the 2-to-4 decoder
    input [3:0] a,    // Input A for the adder-subtractor
    input [3:0] b,    // Input B for the adder-subtractor
    input sub,         // Subtraction flag for the adder-subtractor
    output [3:0] q,    // Output from the functional module
    output overflow   // Overflow output from the adder-subtractor
);

    // 2-to-4 decoder module
    wire [3:0] dec_out;
    decoder_2to4 dec_2to4(
        .in(in),
        .out(dec_out)
    );

    // Adder-subtractor module
    wire [3:0] addsub_out;
    wire addsub_overflow;
    adder_subtractor addsub(
        .a(a),
        .b(b),
        .sub(sub),
        .q(addsub_out),
        .overflow(addsub_overflow)
    );

    // Functional module
    assign q = (dec_out[0] == 0) ? addsub_out : 4'b0;
    assign overflow = (dec_out[0] == 0) ? addsub_overflow : (dec_out[1] | dec_out[2] | dec_out[3]);

endmodule

module top_module (
    input [3:0] A, // 4-bit input to be shifted and multiplied by 3
    input [1:0] shift_type, // 2-bit control signal to select the type of shift operation
    input select, // 1-bit control signal to select between multiplication and shift operation
    output reg [3:0] B // 4-bit output of the active module
);

    // Multiplication module
    wire [6:0] mul_output;
    assign mul_output = A * 3;

    // Barrel shifter module
    wire [3:0] shift_output;
    barrel_shifter barrel_shifter_inst(
        .in(A),
        .out(shift_output),
        .shift_type(shift_type)
    );

    // Additive control logic
    always @(*) begin
        if (select == 0) begin
            B <= mul_output[3:0];
        end else begin
            B <= shift_output;
        end
    end

endmodule

// Barrel shifter module
module barrel_shifter (
    input [3:0] in, // 4-bit input to be shifted
    output reg [3:0] out, // 4-bit output of the shift operation
    input [1:0] shift_type // 2-bit control signal to select the type of shift operation
);

    always @(*) begin
        case (shift_type)
            2'b00: out = in << 1; // Logical left shift
            2'b01: out = in >> 1; // Logical right shift
