    );

    barrel_shifter shifter2(
        .data_in(data_in2),
        .shift_amount(shift_amount2),
        .shift_control(shift_control),
        .shifted_data(shifted_data2)
    );

    bitwise_or or_gate(
        .data1(shifted_data1),
        .data2(shifted_data2),
        .result(result)
    );

endmodule

