module glitch_free_mux (
  input clk1,
  input clk2,
  input ctl,
  output reg clk_out
);

  reg [1:0] sync_clk1, sync_clk2;
  reg [1:0] sync_ctl;
  reg [1:0] sync_out;

  always @(posedge clk1 or posedge clk2) begin
    sync_clk1 <= {sync_clk1[0], clk1};
    sync_clk2 <= {sync_clk2[0], clk2};
  end

  always @(posedge ctl) begin
    sync_ctl <= {sync_ctl[0], ctl};
  end

  always @(posedge sync_clk1[1] or posedge sync_clk2[1]) begin
    if (sync_ctl[1] == 1'b1) begin
      sync_out <= sync_clk1;
    end else begin
      sync_out <= sync_clk2;
    end
  end

  always @(posedge sync_out[0]) begin
    clk_out <= sync_out[1];
  end

endmodule

module fixed_point_arithmetic (
  input signed [integer_bits+fractional_bits-1:0] num1,
  input signed [integer_bits+fractional_bits-1:0] num2,
  input [1:0] ctrl,
  output signed [integer_bits+fractional_bits-1:0] result
);

parameter integer_bits = 4;
parameter fractional_bits = 4;

reg signed [integer_bits+fractional_bits-1:0] temp_result;

always @(*) begin
  case(ctrl)
    2'b00: temp_result = num1 + num2; // addition
    2'b01: temp_result = num1 - num2; // subtraction
    2'b10: temp_result = num1 * num2; // multiplication
    2'b11: temp_result = (num1 << fractional_bits) / num2; // division
  endcase
end

assign result = temp_result;

endmodule

module rx_fifo(
  rst,
  wr_clk,
  rd_clk,
  din,
  wr_en,
  rd_en,
  dout,
  full,
  empty,
  rd_data_count
);

input rst;
input wr_clk;
input rd_clk;
input [7 : 0] din;
input wr_en;
input rd_en;
output [63 : 0] dout;
output full;
output empty;
output [7 : 0] rd_data_count;

reg [7:0] fifo_mem[0:15];
reg [3:0] rd_ptr = 0;
reg [3:0] wr_ptr = 0;
reg [7:0] rd_data_count_reg = 0;

assign full = (rd_ptr == wr_ptr) && rd_data_count_reg;
assign empty = (rd_ptr == wr_ptr) && !rd_data_count_reg;
assign rd_data_count = rd_data_count_reg;

always @(posedge wr_clk) begin
  if (rst) begin
    rd_ptr <= 0;
    wr_ptr <= 0;
    rd_data_count_reg <= 0;
  end else if (wr_en && !full) begin
    fifo_mem[wr_ptr] <= din;
    wr_ptr <= wr_ptr + 1;
    rd_data_count_reg <= rd_data_count_reg + 1;
  end
end

always @(posedge rd_clk) begin
  if (rst) begin
    rd_ptr <= 0;
    wr_ptr <= 0;
    rd_data_count_reg <= 0;
  end else if (rd_en && !empty) begin
    dout <= {fifo_mem[rd_ptr], {56{1'b0}}};
    rd_ptr <= rd_ptr + 1;
    rd_data_count_reg <= rd_data_count_reg - 1;
  end
end

endmodule

