module ddr3_int_phy_alt_mem_phy_mimic_debug(
        // Inputs

        // Clocks 
        measure_clk,    // full rate clock from PLL

        // Active low reset                             
        reset_measure_clk_n, 

        mimic_recapture_debug_data, // from user board button

        mmc_seq_done,   // mimic calibration finished for the current PLL phase
        mmc_seq_value   // result value of the mimic calibration        

        );


   // Parameters 

   parameter NUM_DEBUG_SAMPLES_TO_STORE = 4096;   // can range from 4096 to 524288
   parameter PLL_STEPS_PER_CYCLE        = 24;     // can  range from 16 to 48  

   input wire measure_clk;  
   input wire reset_measure_clk_n;

   input wire mimic_recapture_debug_data;

   input wire mmc_seq_done; 
   input wire mmc_seq_value; 


   function integer clogb2;
      input [31:0] value;
      for (clogb2=0; value>0; clogb2=clogb2+1)
          value = value >> 1;
   endfunction // clogb2


   parameter RAM_WR_ADDRESS_WIDTH = clogb2(NUM_DEBUG_SAMPLES_TO_STORE - 1); // can range from 12 to 19 


   reg                                       s_clr_ram_wr_address_count; 

   reg [(clogb2(PLL_STEPS_PER_CYCLE)-1) : 0] mimic_sample_count;        

   reg [RAM_WR_ADDRESS_WIDTH-1 : 0 ]         ram_write_address; 
   wire                                      ram_wr_enable;             
   wire [0:0]                                debug_ram_data;            
   reg                                       clear_ram_wr_enable;               

   reg [1:0]                                 mimic_recapture_debug_data_metastable; 

   wire                                      mimic_done_in_dbg; // for internal use, just 1 measure_clk cycles long
   reg                                       mmc_seq_done_r;               


   // generate mimic_done_in_debug : a single clock wide pulse based on the rising edge of mmc_seq_done:

   always @ (posedge measure_clk or negedge reset_measure_clk_n)
   begin  
     if (reset_measure_clk_n == 1'b0)      // asynchronous reset (active low)
     begin
         mmc_seq_done_r <= 1'b0;
     end
     else

     begin
         mmc_seq_done_r <= mmc_seq_done;
     end

   end


   assign mimic_done_in_dbg   = mmc_seq_done && !mmc_seq_done_r;  

   assign ram_wr_enable       = mimic_done_in_dbg && !clear_ram_wr_enable;
   assign debug_ram_data[0]   = mmc_seq_value;



  altsyncram #(

                .clock_enable_input_a   ( "BYPASS"),
                .clock_enable_output_a  ( "BYPASS"),
                .intended_device_family ( "Stratix II"),
                .lpm_hint               ( "ENABLE_RUNTIME_MOD=YES, INSTANCE_NAME=MRAM"),
                .lpm_type               ( "altsyncram"),
                .maximum_depth          ( 4096),
                .numwords_a             ( 4096),
                .operation_mode         ( "SINGLE_PORT"),
                .outdata_aclr_a         ( "NONE"),
                .outdata_reg_a          ( "UNREGISTERED"),
                .power_up_uninitialized ( "FALSE"),
                .widthad_a              ( 12),
                .width_a                ( 1),
                .width_byteena_a        ( 1)
        )
         altsyncram_component (
                .wren_a                 ( ram_wr_enable),
                .clock0                 ( measure_clk),
                .address_a              ( ram_write_address),
                .data_a                 ( debug_ram_data),
                .q_a                    ( )
        );




  //  Metastability_mimic_recapture_debug_data : 
  always @(posedge measure_clk or negedge reset_measure_clk_n)
  begin

    if (reset_measure_clk_n == 1'b0)
    begin 
        mimic_recapture_debug_data_metastable    <=  2'b0;
    end
    else

    begin
        mimic_recapture_debug_data_metastable[0] <= mimic_recapture_debug_data;
        mimic_recapture_debug_data_metastable[1] <= mimic_recapture_debug_data_metastable[0];   
    end

  end 



  //mimic_sample_counter : 
  always @(posedge measure_clk or negedge reset_measure_clk_n)
  begin

    if (reset_measure_clk_n == 1'b0) 
    begin
        mimic_sample_count <= 0;        // (others => '0'); 
    end  
    else

    begin
      if (mimic_done_in_dbg == 1'b1)
      begin
          mimic_sample_count <= mimic_sample_count + 1'b1;       

          if (mimic_sample_count == PLL_STEPS_PER_CYCLE-1)
          begin
              mimic_sample_count <= 0; //(others => '0');
          end

      end 

    end 

  end 



  //RAMWrAddressCounter : 
  always @(posedge measure_clk or negedge reset_measure_clk_n)
  begin

      if (reset_measure_clk_n == 1'b0)
      begin
          ram_write_address <= 0;      //(others => '0');   
          clear_ram_wr_enable <= 1'b0;
      end
      else

      begin

          if (s_clr_ram_wr_address_count == 1'b1) // then --Active high synchronous reset
          begin
              ram_write_address <= 0;      //(others => '0');
              clear_ram_wr_enable <= 1'b1;         
          end

          else       
          begin
              clear_ram_wr_enable <= 1'b0;   

              if (mimic_done_in_dbg == 1'b1)
              begin
                  if (ram_write_address != NUM_DEBUG_SAMPLES_TO_STORE-1)  
                  begin 
                      ram_write_address <= ram_write_address + 1'b1;             
                  end

                  else
                  begin
                      clear_ram_wr_enable <= 1'b1;        
                  end 
              end

          end 

      end

  end 

  //ClearRAMWrAddressCounter : 
  always @(posedge measure_clk or negedge reset_measure_clk_n)
  begin

      if (reset_measure_clk_n == 1'b0)
      begin
          s_clr_ram_wr_address_count <= 1'b0;  
      end       

      else
      begin
          if (mimic_recapture_debug_data_metastable[1] == 1'b1)
          begin
              s_clr_ram_wr_address_count <= 1'b1;
          end

          else if (mimic_sample_count == 0)       
          begin
              s_clr_ram_wr_address_count <= 1'b0;
          end

      end 

  end 

  endmodule

module shift_combination(
    input clk,      // Clock input
    input reset,    // Synchronous active-high reset
    input d,        // 1-bit input for the shift register
    input [4:0] in, // 5-bit input for the combinational circuit
    input enable,   // Enable signal for the control logic module
    output q,       // Output of the shift register
    output out_and, // Output of a 5-input AND gate
    output out_or,  // Output of a 5-input OR gate
    output out_nor  // Output of a 5-input NOR gate
);

reg [2:0] shift_reg; // 3-bit shift register
wire [4:0] decoder_out; // Output of the decoder
wire and_out, or_out, nor_out; // Outputs of the AND, OR, and NOR gates

// Shift register
always @(posedge clk, posedge reset) begin
    if (reset) begin
        shift_reg <= 3'b0; // Reset the shift register to 0
    end else begin
        shift_reg <= {shift_reg[1:0], d}; // Shift the input through the register
    end
end

assign q = shift_reg[2]; // Output of the shift register

// Decoder
decoder dec(
    .in(in),
    .out(decoder_out)
);

// AND gate
assign and_out = enable ? &decoder_out : 1'b0; // Output is 1 if all inputs are 1 and enable is high
assign out_and = and_out;

// OR gate
assign or_out = enable ? |decoder_out : 1'b0; // Output is 0 if all inputs are 0 and enable is high
assign out_or = or_out;

// NOR gate
assign nor_out = enable ? ~|decoder_out : 1'b1; // Output is 1 if all inputs are 0 and enable is high
assign out_nor = nor_out;

endmodule

module pipeline_reg1(clk, reset, toPCInc, toPC, toIR, PCInc, PC, IR,tofirst_multiple,first_multiple,flush); // First pipeline register

    output first_multiple;
    output [15:0] PCInc, PC, IR;
    input  [15:0] toPCInc, toPC, toIR;
    input        reset, clk;
    input tofirst_multiple, flush;
    wire [15:0] inIR;
    wire infirst_multiple;

    assign infirst_multiple = (flush == 1'b1) ? 1'b0 : tofirst_multiple; // introduce a NOP, in the event of a flush
    assign inIR = (flush == 1'b1) ? 16'b1111000000000000 : toIR; // introduce a NOP, in the event of a flush

    register1 pipe1first_multiple(.clk(clk), .out(first_multiple), .in(infirst_multiple), .write(1'b0), .reset(reset));
    register16 pipe1IncPC(.clk(clk), .out(PCInc), .in(toPCInc), .write(1'b0), .reset(reset));
    register16 pipe1PC(.clk(clk), .out(PC), .in(toPC), .write(1'b0), .reset(reset));
    register16 pipe1IR(.clk(clk), .out(IR), .in(inIR), .write(1'b0), .reset(reset));

endmodule

module ripple_addsub (
    input [3:0] A,
    input [3:0] B,
    input sub,
    output reg [3:0] sum,
    output reg carry
);

    always @* begin
        if (sub) begin
            sum = A - B;
            carry = (A >= B) ? 1'b1 : 1'b0;
        end
        else begin
            sum = A + B;
            carry = (sum[3]) ? 1'b1 : 1'b0;
        end
    end

endmodule

module LCB (
  input analog_signal,
  input enable,
  input reset,
  output reg pwm_out
);

parameter pwm_width = 8; // width of the PWM signal
parameter pwm_frequency = 100; // frequency of the PWM signal

reg [pwm_width-1:0] pwm_counter;
reg [pwm_width-1:0] pwm_threshold;

always @(posedge clk) begin
  if (reset) begin
    pwm_counter <= 0;
    pwm_threshold <= 0;
    pwm_out <= 0;
  end else if (enable) begin
    pwm_counter <= pwm_counter + 1;
    if (pwm_counter >= pwm_threshold) begin
      pwm_out <= 1;
    end else begin
      pwm_out <= 0;
    end
  end
end

always @(posedge clk) begin
  if (reset) begin
    pwm_threshold <= 0;
  end else if (enable) begin
    case (analog_signal)
      0: pwm_threshold <= 0;
      1: pwm_threshold <= pwm_width / 8;
      2: pwm_threshold <= pwm_width / 4;
      3: pwm_threshold <= pwm_width / 2;
      default: pwm_threshold <= pwm_width;
    endcase
  end
end

endmodule

module shift_left_register (
    input clk,
    input rst,
    input load,
    input shift,
    input [7:0] input_data,
    output reg [7:0] output_data
);

reg [7:0] stage1;
reg [7:0] stage2;

always @(posedge clk) begin
    if (rst) begin
        stage1 <= 8'b0;
        stage2 <= 8'b0;
    end
    else begin
        if (load) begin
            stage1 <= input_data;
            stage2 <= stage1;
        end
        else if (shift) begin
            stage1 <= stage2 << 1;
            stage2 <= stage1;
        end
    end
end

assign output_data = stage1;

endmodule

module signal_selector (
    input A1,
    input A2,
    input A3,
    input B1,
    input C1,
    output Y,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);

    wire sel1, sel2;

    assign sel1 = (A1 >= A2) && (A1 >= A3);
    assign sel2 = (A2 >= A1) && (A2 >= A3);

    always @(*) begin
        if (sel1) begin
            Y = B1;
        end else if (sel2) begin
            Y = C1;
        end else begin
            Y = B1 ^ C1;
        end
    end

endmodule

module OneHotStateMachine (
  input clk,
  output reg [n-1:0] out
);

parameter n = 4; // number of states in the machine

reg [n-1:0] state; // register to store the current state of the machine

always @(posedge clk) begin
  // determine the next state of the machine
  case(state)
    0: state = 1;
    1: state = 2;
    2: state = 3;
    3: state = 0;
  endcase
end

// set the output signals based on the current state of the machine
always @* begin
  case(state)
    0: out = 4'b0001;
    1: out = 4'b0010;
    2: out = 4'b0100;
    3: out = 4'b1000;
  endcase
end

endmodule

module top_module (
    input [15:0] A,
    input [15:0] B,
    input EN,
    output reg [15:0] Y,
    output overflow,
    output reg [15:0] sum,
    output [15:0] decoder_output
);

    wire [15:0] adder_out;
    wire [3:0] decoder_sel;
    wire decoder_en;

    // Instantiate the 16-bit ripple carry adder module
    ripple_carry_adder adder(
        .A(A),
        .B(B),
        .Cin(1'b0),
        .Sum(adder_out),
        .Cout(overflow)
    );

    // Instantiate the 4-to-16 decoder module
    decoder_4to16 decoder(
        .A(decoder_sel),
        .Y(decoder_output),
        .EN(decoder_en)
    );

    // Assign decoder enable signal
    assign decoder_en = EN;

    // Assign decoder select signal based on adder output
    assign decoder_sel = adder_out[15:12];

    // Assign sum output
    always @(*) begin
        sum = adder_out;
    end

    // Assign Y output
    always @(*) begin
        Y = decoder_output;
    end

endmodule

// 16-bit ripple carry adder module
module ripple_carry_adder (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output reg [15:0] Sum,
    output reg Cout
);

    reg [15:0] temp;

    always @(A or B or Cin) begin
        temp = A + B + Cin;
        Sum = temp[15:0];
        Cout = temp[16];
    end

endmodule

// 4-to-16 decoder module
module decoder_4to16 (
    input [3:0] A,
    output reg [15:0] Y,
    input EN
);

    always @(A or EN) begin
        if (EN) begin
            case (A)
                4'b0000: Y = 16'b0000000000000001;
                4'b0001: Y = 16'b0000000000000010;
                4'b0010: Y = 16'b0000000000000100;
                4'b0011: Y = 16'b0000000000001000;
                4'b0100: Y = 16'b0000000000010000;
                4'b0101: Y = 16'b0000000000100000;
                4'b0110: Y = 16'b0000000001000000;
                4'b0111: Y = 16'b0000000010000000;
                4'b1000: Y = 16'b0000000100000000;
                4'b1001: Y = 16'b0000001000000000;
                4'b1010: Y = 16'b0000010000000000;
                4'b1011: Y = 16'b0000100000000000;
                4'b1100: Y = 16'b0001000000000000;
                4'b1101: Y = 16'b0010000000000000;
                4'b1110: Y = 16'b0100000000000000;
                4'b1111: Y = 16'b1000000000000000;
            endcase
        end else begin
            Y = 16'b0000000000000000;
        end
    end

endmodule

