parameter DEPTH = 32;

reg [DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];
integer i;

always @ (posedge clk) begin
    if (ce) begin
        for (i=0;i<DEPTH-1;i=i+1) begin
