module  niosII_system_altpll_0
	( 
	address,
	areset,
	c0,
	c1,
	clk,
	locked,
	phasedone,
	read,
	readdata,
	reset,
	write,
	writedata);
	input   [1:0]  address;
	input   areset;
	output   c0;
	output   c1;
	input   clk;
	output   locked;
	output   phasedone;
	input   read;
	output   [31:0]  readdata;
	input   reset;
	input   write;
	input   [31:0]  writedata;

	wire  wire_stdsync2_dout;
	wire  [4:0]   wire_sd1_clk;
	wire  wire_sd1_locked;
	(* ALTERA_ATTRIBUTE = {"POWER_UP_LEVEL=HIGH"} *)
	reg	pfdena_reg;
	wire	wire_pfdena_reg_ena;
	reg	prev_reset;
	wire  w_locked;
	wire  w_pfdena;
	wire  w_phasedone;
	wire  w_pll_areset_in;
	wire  w_reset;
	wire  w_select_control;
	wire  w_select_status;

	niosII_system_altpll_0_stdsync_sv6   stdsync2
	( 
	.clk(clk),
	.din(wire_sd1_locked),
	.dout(wire_stdsync2_dout),
	.reset_n((~ reset)));
	niosII_system_altpll_0_altpll_lqa2   sd1
	( 
	.areset((w_pll_areset_in | areset)),
	.clk(wire_sd1_clk),
	.inclk({{1{1'b0}}, clk}),
	.locked(wire_sd1_locked));

	// Set w_select_control and w_select_status based on address
	assign w_select_control = (~address[1]) & address[0];
	assign w_select_status = (~address[1]) & (~address[0]);

	// Set pfdena_reg based on writedata and w_select_control
	always @(posedge clk or posedge reset) begin
		if (reset == 1'b1) pfdena_reg <= {1{1'b1}};
		else if (wire_pfdena_reg_ena == 1'b1) pfdena_reg <= writedata[1];
	end
	assign wire_pfdena_reg_ena = write & w_select_control;

	// Set prev_reset based on reset and w_reset
	always @(posedge clk or posedge reset) begin
		if (reset == 1'b1) prev_reset <= 1'b0;
		else prev_reset <= w_reset;
	end
	assign w_reset = write & w_select_control & writedata[0];

	// Set outputs
	assign c0 = wire_sd1_clk[0];
	assign c1 = wire_sd1_clk[1];
	assign locked = wire_sd1_locked;
	assign phasedone = 1'b0;
	assign w_locked = wire_stdsync2_dout;
	assign w_pfdena = pfdena_reg;
	assign w_phasedone = 1'b1;
	assign w_pll_areset_in = prev_reset;

	// Set readdata based on read, w_select_control, w_pfdena, w_select_status, w_phasedone, w_locked
	assign readdata = {{30{1'b0}}, 
		(read & ((w_select_control & w_pfdena) | (w_select_status & w_phasedone))) ? 1'b1 : 1'b0, 
		(read & ((w_select_control & w_pll_areset_in) | (w_select_status & w_locked))) ? w_locked : 1'b0};
endmodule

module control(
    input [5:0] opcode,
    input [5:0] special,
    input branch_eq,
    output [1:0] if_pc_source,
    output id_rt_is_source,
    output ex_imm_command,
    output ex_alu_src_b,
    output ex_alu_rslt_src,
    output [1:0] ex_dst_reg_sel,
    output [1:0] ex_alu_op,
    output mem_read,
    output mem_write,
    output wb_mem_to_reg,
    output wb_reg_write
);

// Opcodes
localparam LW    = 6'b100011,
           SW    = 6'b101011,
           BEQ   = 6'b000100,
           RTYPE = 6'b000000,
           J     = 6'b000010,
           JAL   = 6'b000011,
           ADDI  = 6'b001000,
           ANDI  = 6'b001100,
           ORI   = 6'b001101,
           XORI  = 6'b001110,
           SLTI  = 6'b001010;

// Special opcodes
localparam JR    = 6'b001000;

// Default values
assign if_pc_source = 2'b00;
assign id_rt_is_source = 1'b0;
assign ex_imm_command = 1'b0;
assign ex_alu_src_b = 1'b0;
assign ex_alu_rslt_src = 1'b0;
assign ex_dst_reg_sel = 2'b00;
assign ex_alu_op = 2'b00;
assign mem_read = 1'b0;
assign mem_write = 1'b0;
assign wb_mem_to_reg = 1'b0;
assign wb_reg_write = 1'b0;

// Memory operations
always @* begin
    if (opcode == LW) begin
        ex_alu_src_b = 1'b1;
        ex_dst_reg_sel = 2'b00;
        ex_alu_op = 2'b00;
        wb_mem_to_reg = 1'b1;
        mem_read = 1'b1;
        wb_reg_write = 1'b1;
    end
    else if (opcode == SW) begin
        ex_alu_src_b = 1'b1;
        ex_dst_reg_sel = 2'b00;
        ex_alu_op = 2'b00;
        mem_write = 1'b1;
    end
end

// R-type operations
always @* begin
    if (opcode == RTYPE) begin
        id_rt_is_source = 1'b1;
        ex_alu_src_b = 1'b0;
        ex_dst_reg_sel = 2'b01;
        ex_alu_op = special[2:0];
        wb_reg_write = 1'b1;
    end
end

// Immediate operations
always @* begin
    if (opcode == ADDI || opcode == ANDI || opcode == ORI || opcode == XORI || opcode == SLTI) begin
        ex_imm_command = 1'b1;
        ex_alu_src_b = 1'b1;
        ex_dst_reg_sel = 2'b00;
        ex_alu_op = special[2:0];
        wb_reg_write = 1'b1;
    end
end

// Branch operations
always @* begin
    if (opcode == BEQ) begin
        if (branch_eq) begin
            if_pc_source = 2'b01;
        end
    end
end

// Jump operations
always @* begin
    if (opcode == J) begin
        if_pc_source = 2'b10;
    end
    else if (opcode == JAL) begin
        ex_dst_reg_sel = 2'b10;
        ex_alu_rslt_src = 1'b1;
        wb_reg_write = 1'b1;
    end
end

// JR operation
always @* begin
    if (opcode == RTYPE && special == JR) begin
        if_pc_source = 2'b11;
    end
end

endmodule

