module mmu(clk, reset, fnc, virt, phys,
           tlb_index, tlb_index_new,
           tlb_entry_hi, tlb_entry_hi_new,
           tlb_entry_lo, tlb_entry_lo_new,
           tlb_kmissed, tlb_umissed,
           tlb_invalid, tlb_wrtprot);
    input clk;
    input reset;
    input [2:0] fnc;
    input [31:0] virt;
    output [31:0] phys;
    input [31:0] tlb_index;
    output [31:0] tlb_index_new;
    input [31:0] tlb_entry_hi;
    output [31:0] tlb_entry_hi_new;
    input [31:0] tlb_entry_lo;
    output [31:0] tlb_entry_lo_new;
    output tlb_kmissed;
    output tlb_umissed;
    output tlb_invalid;
    output tlb_wrtprot;

  // fnc = 000    no operation, hold output
  //       001    map virt to phys address
  //       010    tbs
  //       011    tbwr
  //       100    tbri
  //       101    tbwi
  //       110    undefined
  //       111    undefined

  // Define constants
  parameter TLB_SIZE = 32;
  parameter PAGE_BITS = 20;
  parameter FRAME_BITS = 20;
  parameter PAGE_SIZE = 1 << PAGE_BITS;
  parameter FRAME_SIZE = 1 << FRAME_BITS;

  // Define wires and registers
  wire map;
  wire tbs;
  wire tbwr;
  wire tbri;
  wire tbwi;
  reg [PAGE_BITS-1:0] page;
  reg [11:0] offset;
  wire [PAGE_BITS-1:0] tlb_page;
  wire tlb_miss;
  wire [4:0] tlb_found;
  wire tlb_enable;
  wire [FRAME_BITS-1:0] tlb_frame;
  wire tlb_wbit;
  wire tlb_vbit;
  wire [4:0] rw_index;
  wire [PAGE_BITS-1:0] r_page;
  wire [FRAME_BITS-1:0] r_frame;
  wire w_enable;
  wire [PAGE_BITS-1:0] w_page;
  wire [FRAME_BITS-1:0] w_frame;
  wire direct;
  wire [FRAME_BITS-2:0] frame;
  reg [4:0] random_index;
  reg tlb_miss_delayed;

  // decode function
  assign map = (fnc == 3'b001) ? 1 : 0;
  assign tbs = (fnc == 3'b010) ? 1 : 0;
  assign tbwr = (fnc == 3'b011) ? 1 : 0;
  assign tbri = (fnc == 3'b100) ? 1 : 0;
  assign tbwi = (fnc == 3'b101) ? 1 : 0;

  // latch virtual address
  always @(posedge clk) begin
    if (map == 1) begin
      page <= virt[31:12];
      offset <= virt[11:0];
    end
  end

  // create tlb instance
  assign tlb_page = (tbs == 1) ? tlb_entry_hi[31:12] : virt[31:12];
  assign tlb_enable = map;
  assign tlb_wbit = tlb_frame[1];
  assign tlb_vbit = tlb_frame[0];
  assign rw_index = (tbwr == 1) ? random_index : tlb_index[4:0];
  assign tlb_index_new = { tlb_miss | tlb_index[31],
                           tlb_index[30:5], tlb_found };
  assign tlb_entry_hi_new = { ((tbri == 1) ? r_page : page),
                              tlb_entry_hi[11:0] };
  assign tlb_entry_lo_new = { tlb_entry_lo[31:30], r_frame[FRAME_BITS-1:2],
                              tlb_entry_lo[11:2], r_frame[1:0] };
  assign w_enable = tbwr | tbwi;
  assign w_page = tlb_entry_hi[31:12];
  assign w_frame = { tlb_entry_lo[FRAME_BITS-2:12], tlb_entry_lo[1:0] };
  tlb tlb1(tlb_page, tlb_miss, tlb_found,
           clk, tlb_enable, tlb_frame,
           rw_index, r_page, r_frame,
           w_enable, w_page, w_frame);

  // construct physical address
  assign direct = (page[PAGE_BITS-2:PAGE_BITS-1] == 2'b11) ? 1 : 0;
  assign frame = (direct == 1) ? page[PAGE_BITS-1:FRAME_BITS] : tlb_frame[FRAME_BITS-1:1];
  assign phys = { 2'b00, frame, offset };

  // generate "random" index
  always @(posedge clk) begin
    if (reset == 1) begin
      // the index register is counting down
      // so we must start at topmost index
      random_index <= TLB_SIZE-1;
    end else begin
      // decrement index register "randomly"
      // (whenever there is a mapping operation)
      // skip "fixed" entries (0..3)
      if (map == 1) begin
        if (random_index == 4'd4) begin
          random_index <= TLB_SIZE-1;
        end else begin
          random_index <= random_index - 1;
        end
      end
    end
  end

  // generate TLB exceptions
  always @(posedge clk) begin
    if (map == 1) begin
      tlb_miss_delayed <= tlb_miss;
    end
  end
  assign tlb_kmissed = tlb_miss_delayed & ~direct & page[PAGE_BITS-1];
  assign tlb_umissed = tlb_miss_delayed & ~direct & ~page[PAGE_BITS-1];
  assign tlb_invalid = ~tlb_vbit & ~direct;
  assign tlb_wrtprot = ~tlb_wbit & ~direct;

endmodule

module singlecycleprocessor (
    input clk, reset,
    output reg [15:0] WAinstrD, WAinstrF, jumpaddr
);

    /* Registers */
    reg [15:0] PC;
    reg [15:0] IR;
    reg [15:0] A;
    reg [15:0] B;
    reg [15:0] ALUOut;
    reg [3:0] opcode;
    reg [3:0] funct;

    /* Control Signals */
    reg RegWrite;
    reg MemRead;
    reg MemWrite;
    reg ALUSrc;
    reg [1:0] ALUOp;
    reg Branch;
    reg Jump;

    /* Memory */
    reg [15:0] mem [0:255];

    /* Instruction Fetch (IF) */
    wire [15:0] PCPrime;
    assign PCPrime = Branch ? {PC[14:0], IR[7:0], 1'b0} : PC + 1;
    wire [15:0] PCJump;
    assign PCJump = {PC[15:12], IR[7:0], 1'b0};

    /* Instruction Decode (ID) */
    assign opcode = IR[15:12];
    assign funct = IR[3:0];
    wire [3:0] rs = IR[11:8];
    wire [3:0] rt = IR[7:4];
    wire [3:0] rd = IR[3:0];
    wire [15:0] sign_ext = {{12{IR[3]}}, IR[2:0], 12'b0};

    /* Execution (EX) */
    wire [15:0] ALUIn2;
    assign ALUIn2 = ALUSrc ? sign_ext : B;
    wire [15:0] ALUOut;
    assign ALUOut = (ALUOp == 2'b00) ? A + ALUIn2 :
                    (ALUOp == 2'b01) ? A - ALUIn2 :
                    (ALUOp == 2'b10) ? A & ALUIn2 :
                    (ALUOp == 2'b11) ? A | ALUIn2 :
                    A ^ ALUIn2;

    /* Memory (MEM) */
    wire [15:0] MemOut;
    assign MemOut = mem[ALUOut];

    /* Write Back (WB) */
    always @(posedge clk) begin
        if (reset) begin
            A <= 0;
            B <= 0;
            PC <= 0;
            IR <= 0;
            RegWrite <= 0;
            MemRead <= 0;
            MemWrite <= 0;
            ALUSrc <= 0;
            ALUOp <= 0;
            Branch <= 0;
            Jump <= 0;
        end else begin
            IR <= mem[PC];
            A <= (RegWrite && (rd != 4'b0000)) ? ALUOut : A;
            B <= (RegWrite && (rd == 4'b0000)) ? ALUOut : B;
            PC <= Jump ? PCJump : PCPrime;
            RegWrite <= (opcode == 4'b0000) ? 1'b1 : 1'b0;
            MemRead <= (opcode == 4'b0010) ? 1'b1 : 1'b0;
            MemWrite <= (opcode == 4'b0011) ? 1'b1 : 1'b0;
            ALUSrc <= (opcode == 4'b0000 || opcode == 4'b0001 || opcode == 4'b0010) ? 1'b0 : 1'b1;
            ALUOp <= (opcode == 4'b0000) ? 2'b00 :
                     (opcode == 4'b0001) ? 2'b01 :
                     (opcode == 4'b0010) ? 2'b10 :
                     (opcode == 4'b0011 && funct == 4'b0000) ? 2'b00 :
                     (opcode == 4'b0011 && funct == 4'b0001) ? 2'b01 :
                     (opcode == 4'b0011 && funct == 4'b0010) ? 2'b10 :
                     (opcode == 4'b0011 && funct == 4'b0011) ? 2'b11 :
                     2'b00;
            Branch <= (opcode == 4'b0001 && A == B) ? 1'b1 : 1'b0;
            Jump <= (opcode == 4'b0011 && funct == 4'b0100) ? 1'b1 : 1'b0;
        end
    end

    /* Memory */
    always @(posedge clk) begin
        if (MemWrite) begin
            mem[ALUOut] <= B;
        end
    end

    /* Outputs */
    assign WAinstrD = IR;
    assign WAinstrF = mem[PC];
    assign jumpaddr = PCJump;

endmodule

module rxuart(
   input wire clk,
   input wire resetq,
   input wire uart_rx,      // UART recv wire
   input wire rd,           // read strobe
   output wire valid,       // has data 
   output wire [7:0] data   // data
);

  reg [4:0] bitcount;
  reg [7:0] shifter;

  // bitcount == 11111: idle
  //             0-17:  sampling incoming bits
  //             18:    character received

  // On starting edge, wait 3 half-bits then sample, and sample every 2 bits thereafter

  wire idle = &bitcount;
  assign valid = (bitcount == 18);

  wire sample;
  reg [2:0] hh = 3'b111;
  wire [2:0] hhN = {hh[1:0], uart_rx};
  wire startbit = idle & (hhN[2:1] == 2'b10);
  wire [7:0] shifterN = sample ? {hh[1], shifter[7:1]} : shifter;

  wire ser_clk;

  baudgen2 _baudgen(
    .clk(clk),
    .restart(startbit),
    .ser_clk(ser_clk));

  reg [4:0] bitcountN;
  always @*
    if (startbit)
      bitcountN = 0;
    else if (!idle & !valid & ser_clk)
      bitcountN = bitcount + 5'd1;
    else if (valid & rd)
      bitcountN = 5'b11111;
    else
      bitcountN = bitcount;

  // 3,5,7,9,11,13,15,17
  assign sample = (|bitcount[4:1]) & bitcount[0] & ser_clk;
  assign data = shifter;

  always @(negedge resetq or posedge clk)
  begin
    if (!resetq) begin
      hh <= 3'b111;
      bitcount <= 5'b11111;
      shifter <= 0;
    end else begin
      hh <= hhN;
      bitcount <= bitcountN;
      shifter <= shifterN;
    end
  end
endmodule

module adder_subtractor(A, B, mode, cin, result, cout);
  parameter WIDTH = 4;

  input [WIDTH-1:0] A, B;
  input mode, cin;
  output [WIDTH-1:0] result;
  output cout;

  wire [WIDTH:0] C;
  wire [WIDTH-1:0] A_inv, B_inv, B_neg, sum;

  // Invert A and B for subtraction
  assign A_inv = ~A;
  assign B_inv = ~B;

  // Negate B for subtraction
  assign B_neg = B_inv + 1;

  // Perform addition or subtraction based on mode
  assign sum = (mode == 0) ? A + B : A + B_neg;

  // Calculate carry-out
  assign cout = C[WIDTH];

  // Generate full adders for each bit
  genvar i;
  generate
    for (i = 0; i < WIDTH; i = i + 1) begin: fa
      full_adder fa_inst(.a(sum[i]), .b(C[i]), .cin(cin), .s(result[i]), .cout(C[i+1]));
    end
  endgenerate
endmodule

module full_adder(a, b, cin, s, cout);
  input a, b, cin;
  output s, cout;

  assign s = a ^ b ^ cin;
  assign cout = (a & b) | (cin & (a ^ b));
endmodule

module boolean_gr # (parameter C_BOOLEAN_GENERATOR_NUM = 24) (
    input clk,                          // clock to shift init value in
    input [C_BOOLEAN_GENERATOR_NUM-1:0] boolean_data_i,    	// 24 header pins input
    input start,                        // start reconfigure CFGLUT
    input [31:0] fn_init_value,         // reconfigure CFGLUT value
    input [24:0] boolean_input_sel,      // 5 bits per input pin, 5 input 
    output boolean_data_o            	// output result
    );

    wire ce;
    wire CLR;
    wire [4:0] boolean_i;

    // Convert longer then 1 clocks pulse generated by GPIO write to one clock pulse
    FDCE #(
           .INIT(1'b0) // Initial value of register (1'b0 or 1'b1)
        ) FDCE_inst (
           .Q(Q1),      // 1-bit Data output
           .C(start),      // 1-bit Clock input
           .CE(1'b1),    // 1-bit Clock enable input
           .CLR(CLR),  // 1-bit Asynchronous clear input
           .D(1'b1)       // 1-bit Data input
        );

    FDCE #(
           .INIT(1'b0) // Initial value of register (1'b0 or 1'b1)
        ) FDCE_inst_1 (
           .Q(CLR),      // 1-bit Data output
           .C(clk),      // 1-bit Clock input
           .CE(1'b1),    // 1-bit Clock enable input
           .CLR(1'b0),  // 1-bit Asynchronous clear input
           .D(Q1)       // 1-bit Data input
        );

    boolean_fsm fsm(.clk(clk), .start(CLR), .fn_init_value(fn_init_value), .cdi(cdi), .ce(ce), .done(done));

    boolean_input # (C_BOOLEAN_GENERATOR_NUM) input_sel (.sel(boolean_input_sel), .datapin(boolean_data_i), .boolean_o(boolean_i));

    boolean_lut boolean_bit0 (.clk(clk), .ce(ce), .data_in(boolean_i), .CDI(cdi), .result(boolean_data_o));

endmodule

// Finite State Machine
module boolean_fsm(
    input clk,           // clock
    input start,         // start reconfigure CFGLUT
    input [31:0] fn_init_value, // reconfigure CFGLUT value
    output reg [4:0] cdi, // output CDI signal
    output reg ce,        // output CE signal
    output reg done       // output done signal
    );

    localparam [1:0]
        IDLE = 2'b00,
        RECONFIG = 2'b01,
        WAIT = 2'b10;

    reg [1:0] state, next_state;

    always @(posedge clk) begin
        state <= next_state;
    end

    always @(*) begin
        next_state = state;
        ce = 0;
        cdi = 0;
        done = 0;

        case (state)
            IDLE: begin
                if (start) begin
                    next_state = RECONFIG;
                end
            end

            RECONFIG: begin
                ce = 1;
                cdi = fn_init_value[4:0];
                next_state = WAIT;
            end

            WAIT: begin
                ce = 1;
                done = 1;
            end
        endcase
    end
endmodule

// Input Selection
module boolean_input # (parameter C_BOOLEAN_GENERATOR_NUM = 24) (
    input [24:0] sel,
    input [C_BOOLEAN_GENERATOR_NUM-1:0] datapin,
    output [4:0] boolean_o
    );

    assign boolean_o = {datapin[sel[4:0]*5 +: 5], datapin[sel[9:5]*5 +: 5], datapin[sel[14:10]*5 +: 5], datapin[sel[19:15]*5 +: 5], datapin[sel[24:20]*5 +: 5]};

endmodule

// LUT
module boolean_lut(
    input clk,           // clock
    input ce,            // clock enable
    input [4:0] data_in, // input data
    input [4:0] CDI,     // configuration data input
    output reg result    // output result
    );

    reg [31:0] lut;

    always @(posedge clk) begin
        if (ce) begin
            lut <= CDI;
        end
    end

    always @(*) begin
        result = lut[data_in];
    end
endmodule

// D Flip-Flop with Clear and Enable
module FDCE (
    output reg Q,    // 1-bit Data output
    input C,         // 1-bit Clock input
    input CE,        // 1-bit Clock enable input
    input CLR,       // 1-bit Asynchronous clear input
    input D          // 1-bit Data input
    );

    always @(posedge C) begin
        if (CLR) begin
            Q <= 1'b0;
        end else if (CE) begin
            Q <= D;
        end
    end
endmodule

module tuner_slice_1k #(
    parameter dsz = 10,
              psz = 12
)
(
    input clk, reset, shf_90,
    input signed [dsz-1:0] in,
    input [psz-1:0] phs,
    output reg signed [dsz-1:0] out
);

    reg signed [dsz-1:0] sin_val, cos_val;
    reg signed [dsz-1:0] sin_out, cos_out;
    reg signed [dsz-1:0] i_out, q_out;

    always @(posedge clk)
    begin
        if(reset == 1'b1)
        begin
            sin_val <= 'sd0;
            cos_val <= 'sd0;
            sin_out <= 'sd0;
            cos_out <= 'sd0;
            i_out <= 'sd0;
            q_out <= 'sd0;
            out <= 'sd0;
        end
        else
        begin
            // Calculate sine and cosine values
            sin_val <= $signed($sin((2**10)*$itor(phs)/2**12));
            cos_val <= $signed($cos((2**10)*$itor(phs)/2**12));

            // Multiply input by sine wave
            sin_out <= sin_val * in;

            // Multiply input by cosine wave if shf_90 is high
            if(shf_90)
                cos_out <= cos_val * in;

            // Add sine and cosine outputs
            i_out <= sin_out + cos_out;
            q_out <= sin_out - cos_out;

            // Output i_out or q_out depending on shf_90
            out <= shf_90 ? q_out : i_out;
        end
    end

endmodule

module mod(/*AUTOARG*/
   // Outputs
   m_src_getn, m_dst_putn, m_dst, m_dst_last, m_endn, m_cap,
   // Inputs
   wb_clk_i, m_reset, m_enable, dc, m_src, m_src_last,
   m_src_almost_empty, m_src_empty, m_dst_almost_full, m_dst_full
   );
   input wb_clk_i;
   input m_reset;
   input m_enable;

   wire  wb_rst_i = m_reset;

   input [23:0] dc;   
   output 	m_src_getn;
   input [63:0] m_src;
   input 	m_src_last;
   input 	m_src_almost_empty;
   input 	m_src_empty;

   output 	m_dst_putn;
   output [63:0] m_dst;
   output 	 m_dst_last;
   input 	 m_dst_almost_full;
   input 	 m_dst_full;

   output 	 m_endn;

   output [7:0]  m_cap;

   // synopsys translate_off
   pullup(m_dst_putn);
   pullup(m_src_getn);
   pullup(m_endn);
   // synopsys translate_on

   wire 	 fo_full   = m_dst_full  || m_dst_almost_full;
   wire 	 src_empty = m_src_empty || m_src_almost_empty;

   wire [15:0] 	 en_out_data,  de_out_data;
   wire 	 en_out_valid, de_out_valid;
   wire 	 en_out_done,  de_out_done;

   encode encode(.ce(dc[5] && m_enable),
		 .fi(m_src),
		 .clk(wb_clk_i),
		 .rst(wb_rst_i),
		 .data_o(en_out_data),
		 .done_o(en_out_done),
		 .valid_o(en_out_valid),
		 .m_last(m_src_last),
		 /*AUTOINST*/
		 // Outputs
		 .m_src_getn		(m_src_getn),
		 // Inputs
		 .fo_full		(fo_full),
		 .src_empty		(src_empty));

   decode decode(.ce(dc[6] && m_enable),
		 .fi(m_src),
		 .clk(wb_clk_i),
		 .rst(wb_rst_i),
		 .data_o(de_out_data),
		 .done_o(de_out_done),
		 .valid_o(de_out_valid),
		 .m_last(m_src_last),
		 /*AUTOINST*/
		 // Outputs
		 .m_src_getn		(m_src_getn),
		 // Inputs
		 .fo_full		(fo_full),
		 .src_empty		(src_empty));

   codeout codeout (/*AUTOINST*/
		    // Outputs
		    .m_dst		(m_dst[63:0]),
		    .m_dst_putn		(m_dst_putn),
		    .m_dst_last		(m_dst_last),
		    .m_endn		(m_endn),
		    // Inputs
		    .wb_clk_i		(wb_clk_i),
		    .wb_rst_i		(wb_rst_i),
		    .dc			(dc[23:0]),
		    .en_out_data	(en_out_data[15:0]),
		    .de_out_data	(de_out_data[15:0]),
		    .en_out_valid	(en_out_valid),
		    .de_out_valid	(de_out_valid),
		    .en_out_done	(en_out_done),
		    .de_out_done	(de_out_done),
		    .m_enable		(m_enable));

   assign 	 m_cap = {1'b1,  /* decode */
			  1'b1,  /* encode */
			  1'b0,  /* memcpy */
			  1'b0, 
			  1'b0, 
			  1'b0, 
			  1'b0};

endmodule

module uart_baud_clk
#(
  parameter SYS_CLK_FREQ             = 50000000,
  parameter BAUD                     = 19200,
  parameter BAUD_CLK_OVERSAMPLE_RATE = 16
)
(
  input  wire clk,
  input  wire reset,
  output wire baud_clk_tick
);

localparam [15:0] CLKS_PER_OVERSAMPLE_TICK = (SYS_CLK_FREQ / BAUD) / BAUD_CLK_OVERSAMPLE_RATE;

// Registers
reg  [15:0] q_cnt;
wire [15:0] d_cnt;

always @(posedge clk, posedge reset)
  begin
    if (reset)
      q_cnt <= 0;
    else
      q_cnt <= d_cnt;
  end

assign d_cnt         = (q_cnt == (CLKS_PER_OVERSAMPLE_TICK - 1)) ? 16'h0000 : (q_cnt + 16'h0001);
assign baud_clk_tick = (q_cnt == (CLKS_PER_OVERSAMPLE_TICK - 1)) ? 1'b1     : 1'b0;

endmodule

module byte_reverse_xor(
