module priority_encoder_3bit (
    input A2,
    input A1,
    input A0,
    output EN,
    output reg [2:0] Y
);

reg [2:0] Y_reg;
reg [1:0] stage;

always @(*) begin
    case(stage)
        0: begin
            Y_reg = {A2, A1, A0};
            EN = 0;
            Y = 3'b0;
        end
        1: begin
            if(Y_reg[2] == 1 && Y_reg[1:0] == 2'b00) begin
                EN = 1;
                Y = 3'b100;
            end else begin
                EN = 0;
                Y = 3'b0;
            end
        end
        2: begin
            if(Y_reg[2:1] == 2'b11 && Y_reg[0] == 0) begin
                EN = 1;
                Y = 3'b110;
            end else begin
                EN = 0;
                Y = 3'b0;
            end
        end
        3: begin
            if(Y_reg == 3'b111) begin
                EN = 1;
                Y = 3'b111;
            end else begin
                EN = 0;
                Y = 3'b0;
            end
        end
    endcase
end

always @(posedge clk) begin
    if(reset) begin
        stage <= 0;
    end else begin
        if(stage == 3) begin
            stage <= 0;
        end else begin
            stage <= stage + 1;
        end
    end
end

endmodule

module MAX6682_SPI_FSM (
  input            Reset_n_i,
  input            Clk_i,
  input            SPI_FSM_Start,
  input            SPI_Transmission_i,
  output reg       MAX6682CS_n_o,
  output reg       SPI_Write_o,
  output reg       SPI_ReadNext_o,
  output reg       SPI_FSM_Done,
  input      [7:0] SPI_Data_i,
  output reg [7:0] Byte0,
  output reg [7:0] Byte1
);
  localparam stIdleSPI    = 3'b000;
  localparam stWrite1     = 3'b001;
  localparam stWrite2     = 3'b010;
  localparam stWait       = 3'b011;
  localparam stRead1      = 3'b100;
  localparam stRead2      = 3'b101;
  localparam stPause      = 3'b110;
  reg [2:0]              SPI_FSM_State;
  reg [2:0]              SPI_FSM_NextState;
  reg                    SPI_FSM_Wr1;
  reg                    SPI_FSM_Wr0;

  /////////////////////////////////////////////////////////////////////////////
  // SPI FSM //////////////////////////////////////////////////////////////////
  /////////////////////////////////////////////////////////////////////////////

  always @(negedge Reset_n_i or posedge Clk_i)
  begin
    if (!Reset_n_i)
    begin
      SPI_FSM_State <= stIdleSPI;
      MAX6682CS_n_o <= 1'b1;
      SPI_Write_o <= 1'b0;
      SPI_ReadNext_o <= 1'b0;
      SPI_FSM_Wr1 <= 1'b0;
      SPI_FSM_Wr0 <= 1'b0;
      SPI_FSM_Done <= 1'b0;
      Byte0 <= 8'd0;
      Byte1 <= 8'd0;
    end
    else
    begin // rising clock edge
      SPI_FSM_State <= SPI_FSM_NextState;
      MAX6682CS_n_o <= 1'b0;
      SPI_Write_o <= 1'b0;
      SPI_ReadNext_o <= 1'b0;
      SPI_FSM_Wr1 <= 1'b0;
      SPI_FSM_Wr0 <= 1'b0;
      SPI_FSM_Done <= 1'b0;
    end  
  end

  always @*
  begin  // process SPI_FSM_CombProc
    SPI_FSM_NextState = SPI_FSM_State;
    case (SPI_FSM_State)
      stIdleSPI: begin
        if (SPI_FSM_Start == 1'b1)
        begin
          SPI_FSM_NextState = stWrite1;
          SPI_Write_o = 1'b1;
        end
      end
      stWrite1: begin
        SPI_FSM_NextState = stWrite2;
        SPI_Write_o = 1'b1;
      end
      stWrite2: begin
        SPI_FSM_NextState = stWait;
      end
      stWait: begin
        // wait until SPI transmission has finished
        if (SPI_Transmission_i == 1'b0) begin
          SPI_FSM_NextState = stRead1;
          SPI_ReadNext_o = 1'b1;
          SPI_FSM_Wr1 = 1'b1;
        end
      end
      stRead1: begin
        SPI_FSM_NextState = stRead2;
        SPI_ReadNext_o = 1'b1;
        SPI_FSM_Wr0 = 1'b1;
      end
      stRead2: begin
        SPI_FSM_NextState = stPause;
        SPI_FSM_Done = 1'b1;
      end
      stPause: begin
        SPI_FSM_NextState = stIdleSPI;
        SPI_FSM_Done = 1'b1;
      end
      default: begin
      end
    endcase
  end

  /////////////////////////////////////////////////////////////////////////////
  // Byte-wide Memory /////////////////////////////////////////////////////////
  /////////////////////////////////////////////////////////////////////////////

  always @(negedge Reset_n_i or posedge Clk_i)
  begin
    if (!Reset_n_i)
    begin
      Byte0 <= 8'd0;
      Byte1 <= 8'd0;
    end
    else
    begin
      if (SPI_FSM_Wr0)
      begin
        Byte0 <= SPI_Data_i;
      end
      if (SPI_FSM_Wr1)
      begin
        Byte1 <= SPI_Data_i;
      end
    end  
  end

endmodule

module LogExp (
  input [31:0] in,
  input ctrl,
  output [31:0] out
);

  reg [31:0] ln_out;
  reg [31:0] exp_out;

  always @(*) begin
    if (ctrl == 0) begin
      // Compute natural logarithm
      ln_out = $ln(in);
      out = ln_out;
    end else begin
      // Compute exponential
      exp_out = $exp(in);
      out = exp_out;
    end
  end

endmodule

module magnitude_comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output EQ,
    output GT,
    output LT
);

    reg [2:0] result;

    always @* begin
        case (A > B)
            1'b0: result = (A == B) ? 3'b100 : 3'b001;
            1'b1: result = 3'b010;
        endcase
    end

    assign EQ = (result == 3'b100);
    assign GT = (result == 3'b010);
    assign LT = (result == 3'b001);

endmodule

module shift_addsub (
    input clk,
    input reset,
    input SER,
    input [3:0] A,
    input [3:0] B,
    input sub,
    output [3:0] result
);

    reg [3:0] Q;
    wire [3:0] shifted_Q;
    wire [3:0] added_A;
    wire [3:0] subbed_A;

    shift_register shift_reg (
        .clk(clk),
        .reset(reset),
        .SER(SER),
        .SHIFT(shifted_Q),
        .LOAD(Q)
    );

    adder_subtractor addsub (
        .A(A),
        .B(shifted_Q),
        .sub(sub),
        .result(added_A),
        .sub_result(subbed_A)
    );

    assign result = (sub) ? subbed_A : added_A;

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] a,
    input [3:0] b,
    input select, // Select input to choose between addition and subtraction
    input shift_parallel,
    input [3:0] parallel_in,
    output [3:0] sum,
    output overflow,
    output [3:0] shift_reg_out,
    output [3:0] func_out // Bitwise OR output of shift register and result
);

reg [3:0] shift_reg;
reg [3:0] result;
reg [1:0] operation;
wire [3:0] bitwise_or;

assign bitwise_or = shift_reg | result;

// Shift register module
shift_register shift_reg_module (
    .clk(clk),
    .reset(reset),
    .parallel_in(parallel_in),
    .shift(shift_parallel),
    .parallel_out(shift_reg_out),
    .serial_out(shift_reg)
);

// Adder-subtractor module
adder_subtractor add_sub_module (
    .a(a),
    .b(b),
    .select(select),
    .sum(sum),
    .overflow(overflow),
    .result(result),
    .operation(operation)
);

// Functional module for bitwise OR
assign func_out = bitwise_or;

endmodule

// Shift register module
module shift_register (
    input clk,
    input reset,
    input [3:0] parallel_in,
    input shift,
    output [3:0] parallel_out,
    output [3:0] serial_out
);

reg [3:0] shift_reg;

