    reg [3:0] binary_reg;

    binary_to_bcd bcd_converter(
        .binary_in(binary_reg),
        .bcd_out(bcd_out)
    );

    always @(posedge clk or negedge reset) begin
        if (reset == 0) begin
            binary_reg <= 4'b0000;
        end else if (slowena == 1) begin
            binary_reg <= binary_reg + 1;
        end
    end

    assign binary_out = binary_reg;

endmodule

